-- -----------------------------------------------------------------------------
-- FAQ generales
-- -----------------------------------------------------------------------------
insert into public.faqs (scope, question, answer, position) values
('general', '¿Cuánto cuesta una web con Novalius?', 'Depende del alcance: número de páginas, diseño, funcionalidades e integraciones. Nova puede darte una estimación orientativa en minutos y, si quieres, preparamos una propuesta personalizada con el precio definitivo.', 0),
('general', '¿Cuánto se tarda en tener la web publicada?', 'Lo fijamos en la propuesta según el alcance y la disponibilidad de contenidos. Trabajamos con entregas parciales para que veas avances desde las primeras semanas.', 1),
('general', '¿Podré editar la web yo mismo?', 'Sí. Siempre que lo necesites incluimos un panel de gestión para que puedas cambiar textos, imágenes y secciones sin tocar código.', 2),
('general', '¿La web será mía?', 'Sí. El dominio, el contenido y los accesos son tuyos. Te entregamos documentación y credenciales al finalizar.', 3),
('general', '¿Qué es Nova?', 'Nova es el asistente con inteligencia artificial de Novalius. Te orienta sobre servicios, calcula presupuestos orientativos y, si lo autorizas, envía tu solicitud al equipo. Sus respuestas pueden contener errores y no sustituyen una propuesta formal.', 4),
('general', '¿Ofrecéis mantenimiento después de la entrega?', 'Sí. Tenemos planes de mantenimiento con actualizaciones, copias de seguridad, monitorización y mejoras continuas.', 5);

-- FAQ del Challenge
insert into public.faqs (scope, question, answer, position) values
('challenge', '¿Qué necesito para jugar?', 'Una cuenta de Novalius con el correo verificado. Así podemos asociar el cupón a tu cuenta y evitar abusos.', 0),
('challenge', '¿Cómo gano el quiz?', 'Debes acertar las diez preguntas antes de que acabe el tiempo. El tiempo lo mide nuestro servidor, no tu navegador.', 1),
('challenge', '¿Se puede ganar a Nova al tres en raya?', 'Sí. En los niveles con recompensa Nova juega con estrategia real, pero comete errores ocasionales. En el nivel experto se equivoca muy poco.', 2),
('challenge', '¿Cuántos cupones puedo conseguir?', 'Uno por cuenta. El cupón es personal, de un solo uso y caduca en la fecha indicada en tu cuenta.', 3),
('challenge', '¿Cómo uso el cupón?', 'Indícalo al solicitar tu propuesta o en tu cuenta. El equipo lo valida y lo aplica al presupuesto de un nuevo proyecto según las condiciones del cupón.', 4);

-- FAQ por servicio
insert into public.faqs (scope, service_id, question, answer, position)
select 'service', s.id, f.q, f.a, f.pos
from public.services s
join (values
  ('diseno-web', '¿Usáis plantillas?', 'Partimos de un diseño propio para cada proyecto. Las plantillas de nuestra galería sirven como punto de partida rápido cuando el cliente lo prefiere, siempre adaptadas a su marca.', 0),
  ('diseno-web', '¿La web estará optimizada para móviles?', 'Sí. Diseñamos la experiencia móvil de forma específica, no como una versión reducida del escritorio.', 1),
  ('seo', '¿Cuándo se ven resultados de SEO?', 'El SEO es un trabajo acumulativo. Las mejoras técnicas pueden notarse pronto, pero el posicionamiento estable suele requerir varios meses de trabajo constante.', 0),
  ('seo', '¿Garantizáis la primera posición en Google?', 'No. Nadie puede garantizarlo honestamente. Aplicamos buenas prácticas y medimos la evolución con datos reales.', 1),
  ('automatizaciones-ia', '¿Qué herramientas podéis conectar?', 'Cualquier servicio con API o integración oficial: correo, CRM, hojas de cálculo, facturación, calendarios, tiendas online y más.', 0),
  ('automatizaciones-ia', '¿La IA toma decisiones sola?', 'Solo cuando tú lo decides. Podemos añadir puntos de aprobación para que una persona valide antes de ejecutar acciones importantes.', 1),
  ('asistentes-ia', '¿El asistente puede inventar respuestas?', 'Lo limitamos a la información de tu base de conocimiento y le indicamos que derive a tu equipo cuando no sabe algo. Aun así, conviene revisar sus conversaciones periódicamente.', 0),
  ('asistentes-ia', '¿Puedo cambiar lo que sabe el asistente?', 'Sí. Su conocimiento, su tono y sus instrucciones se editan desde el panel sin programar.', 1),
  ('paneles-administrativos', '¿Puedo usar el panel desde el móvil?', 'Sí. Todos los paneles son responsive, aunque las tareas de edición complejas se optimizan para escritorio.', 0),
  ('bases-de-datos', '¿Podéis migrar mis hojas de cálculo?', 'Sí. Limpiamos, validamos e importamos tus datos existentes a la nueva base de datos.', 0),
  ('integraciones', '¿Qué pasa si un servicio externo falla?', 'Diseñamos las integraciones con reintentos, registro de errores y avisos para que nada se pierda en silencio.', 0),
  ('mantenimiento', '¿Qué incluye el mantenimiento?', 'Actualizaciones, copias de seguridad, monitorización y una bolsa de horas para mejoras, según el plan contratado.', 0),
  ('rediseno-web', '¿Perderé mi posicionamiento al rediseñar?', 'Planificamos redirecciones y migración de contenidos para conservar el posicionamiento existente.', 0),
  ('chatbots', '¿Qué diferencia hay entre un chatbot y un asistente con IA?', 'Un chatbot puede seguir flujos guiados; un asistente con IA entiende lenguaje natural y razona con tu información. Muchas veces combinamos ambos.', 0),
  ('aplicaciones-web', '¿Quién es el propietario del software?', 'Tú. Definimos en la propuesta la cesión de derechos y la entrega del código.', 0)
) as f(slug, q, a, pos) on f.slug = s.slug;
